/**
 * entranceExamAI.ts — AI-powered content generation for entrance exams.
 * 
 * Uses a hybrid approach:
 * - Dates, fees, eligibility are extracted via CODE (regex) — never delegated to AI
 * - FAQs, SEO, content modules are generated by AI using the raw context
 */
import { generateWithGemini } from "./client";

