// ── Date Pre-Parser (CODE-BASED — no AI needed) ────────────────────────────

const MONTH_MAP: Record<string, string> = {
  jan: "01", january: "01", feb: "02", february: "02", mar: "03", march: "03",
  apr: "04", april: "04", may: "05", jun: "06", june: "06",
  jul: "07", july: "07", aug: "08", august: "08", sep: "09", september: "09",
  oct: "10", october: "10", nov: "11", november: "11", dec: "12", december: "12",
};

function parseDate(text: string, defaultYear: number): string {
  // "Aug 3, 2026" or "AUG 03, 2026" or "3 Aug 2026" or "August 3, 2026"
  const patterns = [
    /(\w+)\s+(\d{1,2}),?\s*(\d{4})/i,  // "Aug 3, 2026" / "August 3 2026"
    /(\d{1,2})\s+(\w+),?\s*(\d{4})/i,  // "3 Aug 2026"
    /(\d{1,2})[-/](\d{1,2})[-/](\d{4})/,  // "03-08-2026" or "03/08/2026"
  ];

  // Pattern 1: Month Day, Year
  let m = text.match(patterns[0]);
  if (m) {
    const month = MONTH_MAP[m[1].toLowerCase()];
    if (month) return `${m[3]}-${month}-${m[2].padStart(2, "0")}`;
  }

  // Pattern 2: Day Month Year
  m = text.match(patterns[1]);
  if (m) {
    const month = MONTH_MAP[m[2].toLowerCase()];
    if (month) return `${m[3]}-${month}-${m[1].padStart(2, "0")}`;
  }

  // Pattern 3: DD-MM-YYYY or DD/MM/YYYY
  m = text.match(patterns[2]);
  if (m) return `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`;

  // "First week of January 2027" → 2027-01-07
  m = text.match(/first\s+week\s+of\s+(\w+)\s+(\d{4})/i);
  if (m) {
    const month = MONTH_MAP[m[1].toLowerCase()];
    if (month) return `${m[2]}-${month}-07`;
  }

  // Just "January 2027" → 2027-01-15
  m = text.match(/(\w+)\s+(\d{4})/i);
  if (m) {
    const month = MONTH_MAP[m[1].toLowerCase()];
    if (month) return `${m[2]}-${month}-15`;
  }

  return "";
}

interface DateLabel {
  patterns: RegExp[];
  label: string;
  isUrgent: boolean;
}

const DATE_LABELS: DateLabel[] = [
  { patterns: [/notification\s*(release|published|out)/i, /bulletin\s*(release|published)/i], label: "Notification Release", isUrgent: false },
  { patterns: [/registration\s*(opens|starts|begins)/i, /application\s*(opens|starts|begins)/i], label: "Registration Opens", isUrgent: true },
  { patterns: [/registration\s*(closes|ends|deadline)/i, /last\s*date\s*(to\s*apply|of\s*registration)/i, /application\s*(closes|ends|deadline)/i], label: "Registration Closes", isUrgent: true },
  { patterns: [/correction\s*window/i, /edit\s*application/i, /modify\s*application/i], label: "Application Correction Window", isUrgent: false },
  { patterns: [/admit\s*card\s*(download|release|available)/i, /hall\s*ticket/i], label: "Admit Card Release", isUrgent: false },
  { patterns: [/exam\s*date/i, /test\s*day/i, /test\s*date/i, /date\s*of\s*exam/i], label: "Exam Date", isUrgent: true },
  { patterns: [/answer\s*key/i, /objection\s*window/i], label: "Answer Key Release", isUrgent: false },
  { patterns: [/result\s*(declaration|declared|announced|date)/i, /score\s*card/i], label: "Result Declaration", isUrgent: false },
  { patterns: [/counselling|counseling|allotment/i], label: "Counselling Starts", isUrgent: false },
  { patterns: [/cut\s*off\s*(release|declared)/i], label: "Cutoff Release", isUrgent: false },
];

function extractDatesFromRaw(rawContent: string, year: number): { label: string; date: string; isUrgent: boolean }[] {
  const results: { label: string; date: string; isUrgent: boolean }[] = [];
  const lines = rawContent.split(/[\n\r]+/);

  for (const line of lines) {
    for (const dl of DATE_LABELS) {
      for (const pattern of dl.patterns) {
        if (pattern.test(line)) {
          const date = parseDate(line, year);
          if (date) {
            // Don't add duplicates
            if (!results.find((r) => r.label === dl.label)) {
              results.push({ label: dl.label, date, isUrgent: dl.isUrgent });
            }
          }
          break;
        }
      }
    }
  }

  // Also look for tabular data: "Label\tDate" or "Label: Date" patterns
  const tabPatterns = [
    /Registration\s*Opens[:\s]*([A-Za-z]+\s+\d{1,2},?\s*\d{4})/i,
    /Registration\s*Closes[:\s]*([A-Za-z]+\s+\d{1,2},?\s*\d{4})/i,
    /Admit\s*Card[^:]*[:\s]*([A-Za-z]+\s+\d{1,2},?\s*\d{4})/i,
    /Exam\s*Date[:\s]*([A-Za-z]+\s+\d{1,2},?\s*\d{4})/i,
    /Result[^:]*[:\s]*([A-Za-z]+[^,\d]*\d{4})/i,
    /Test\s*Day[:\s]*[A-Za-z]*,?\s*([A-Za-z]+\s+\d{1,2},?\s*\d{4})/i,
  ];

  const labelMap = ["Registration Opens", "Registration Closes", "Admit Card Release", "Exam Date", "Result Declaration", "Exam Date"];

  for (let i = 0; i < tabPatterns.length; i++) {
    if (results.find((r) => r.label === labelMap[i])) continue; // already found
    const match = rawContent.match(tabPatterns[i]);
    if (match) {
      const date = parseDate(match[1], year);
      if (date) {
        const isUrgent = ["Registration Opens", "Registration Closes", "Exam Date"].includes(labelMap[i]);
        results.push({ label: labelMap[i], date, isUrgent });
      }
    }
  }

  return results;
}

// ── AI Date Fallback (tiny prompt, used when regex finds <3 dates) ──────────

const AI_DATE_EXTRACT_PROMPT = (rawContent: string) => `Extract ALL event dates from this text. Return ONLY a JSON array of objects with "label" and "dateText" fields.

TEXT:
${rawContent.slice(0, 3000)}

Return format: [{"label":"event name","dateText":"the date as written in text"}]
Return ONLY the JSON array. No explanation.`;

async function extractDatesWithAI(
  rawContent: string,
  year: number,
  apiKey: string,
  model?: string
): Promise<{ label: string; date: string; isUrgent: boolean }[]> {
  try {
    const raw = await generateWithGemini(AI_DATE_EXTRACT_PROMPT(rawContent), apiKey, model);
    let cleaned = raw.trim();
    if (cleaned.startsWith("```")) cleaned = cleaned.replace(/^```(?:json)?\n?/, "").replace(/\n?```$/, "");
    // Find JSON array
    const arrStart = cleaned.indexOf("[");
    const arrEnd = cleaned.lastIndexOf("]");
    if (arrStart < 0 || arrEnd < 0) return [];
    cleaned = cleaned.slice(arrStart, arrEnd + 1);

    const items = JSON.parse(cleaned) as { label: string; dateText: string }[];
    const results: { label: string; date: string; isUrgent: boolean }[] = [];

    for (const item of items) {
      if (!item.label || !item.dateText) continue;
      const date = parseDate(item.dateText, year);
      if (!date) continue;

      // Map the AI-extracted label to our standard labels
      const standardLabel = mapToStandardLabel(item.label);
      if (!standardLabel) continue;

      const isUrgent = ["Registration Opens", "Registration Closes", "Exam Date"].includes(standardLabel);
      if (!results.find((r) => r.label === standardLabel)) {
        results.push({ label: standardLabel, date, isUrgent });
      }
    }
    return results;
  } catch {
    return []; // Fallback silently fails — regex results are still used
  }
}

function mapToStandardLabel(rawLabel: string): string | null {
  const l = rawLabel.toLowerCase();
  if (/registration\s*(open|start|begin)/i.test(l)) return "Registration Opens";
  if (/registration\s*(close|end|deadline)|last\s*date/i.test(l)) return "Registration Closes";
  if (/exam\s*date|test\s*day|test\s*date/i.test(l)) return "Exam Date";
  if (/admit\s*card|hall\s*ticket/i.test(l)) return "Admit Card Release";
  if (/result|score\s*card/i.test(l)) return "Result Declaration";
  if (/notification|bulletin/i.test(l)) return "Notification Release";
  if (/correction|edit\s*application/i.test(l)) return "Application Correction Window";
  if (/answer\s*key/i.test(l)) return "Answer Key Release";
  if (/counsel/i.test(l)) return "Counselling Starts";
  if (/cut\s*off/i.test(l)) return "Cutoff Release";
  return null;
}

// ── Combined Date Extraction: Regex first, AI fallback if <3 dates ──────────

async function extractAllDates(
  rawContent: string,
  year: number,
  apiKey: string,
  model?: string
): Promise<{ label: string; date: string; isUrgent: boolean }[]> {
  // Step 1: Try regex extraction (instant, free)
  const regexDates = extractDatesFromRaw(rawContent, year);

  // Step 2: If regex found enough dates (3+), use them directly
  if (regexDates.length >= 3) {
    return regexDates;
  }

  // Step 3: Regex found <3 dates — use AI fallback to catch dates in unusual formats
  const aiDates = await extractDatesWithAI(rawContent, year, apiKey, model);

  // Merge: regex results take priority, AI fills gaps
  const merged = [...regexDates];
  for (const aiDate of aiDates) {
    if (!merged.find((r) => r.label === aiDate.label)) {
      merged.push(aiDate);
    }
  }

  return merged;
}

// ── Fee Pre-Parser ─────────────────────────────────────────────────────────

function extractFees(rawContent: string): { general: number; sc: number; st: number; obc: number } | null {
  const generalMatch = rawContent.match(/(?:General|Others|Unreserved)[^₹]*₹\s*([\d,]+)/i) || rawContent.match(/₹\s*([\d,]+)[^₹]*(?:General|Others)/i);
  const scMatch = rawContent.match(/(?:SC|ST|PwBD)[^₹]*₹\s*([\d,]+)/i) || rawContent.match(/₹\s*([\d,]+)[^₹]*(?:SC|ST)/i);

  if (!generalMatch && !scMatch) return null;

  const general = generalMatch ? parseInt(generalMatch[1].replace(/,/g, "")) : 0;
  const sc = scMatch ? parseInt(scMatch[1].replace(/,/g, "")) : 0;

  return { general, sc, st: sc, obc: general };
}

// ── Eligibility Pre-Parser ─────────────────────────────────────────────────

function extractEligibility(rawContent: string): { qualification: string; ageLimit: string; nationality: string; attempts: string } | null {
  const qualMatch = rawContent.match(/(?:Bachelor'?s?\s*degree|Graduation)[^.]*(?:50%|45%)[^.]*\./i);
  if (!qualMatch) return null;

  return {
    qualification: qualMatch[0].trim(),
    ageLimit: rawContent.match(/(?:age\s*limit|upper\s*age)[^.]*\./i)?.[0]?.trim() || "No upper age limit",
    nationality: "Indian citizens",
    attempts: rawContent.match(/(?:attempt|number\s*of\s*attempts)[^.]*\./i)?.[0]?.trim() || "No limit on attempts",
  };
}

