export async function generateExamDataWithAI(
  examName: string,
  year: number,
  apiKey: string,
  model?: string,
  rawContent?: string
): Promise<AIExamData> {
  // ── Step 1: Pre-parse dates, fees, eligibility from raw content (CODE, not AI) ──
  let preExtractedDates: { label: string; date: string; isUrgent: boolean }[] = [];
  let preExtractedFees: { general: number; sc: number; st: number; obc: number } | null = null;
  let preExtractedEligibility: { qualification: string; ageLimit: string; nationality: string; attempts: string } | null = null;

  if (rawContent) {
    preExtractedDates = await extractAllDates(rawContent, year, apiKey, model);
    preExtractedFees = extractFees(rawContent);
    preExtractedEligibility = extractEligibility(rawContent);
  }

  // ── Step 2: Send to AI for FAQs, SEO, content modules (NOT dates) ──
  const prompt = rawContent
    ? GENERATE_WITH_RAW_PROMPT(examName, year, rawContent)
    : GENERATE_PROMPT(examName, year);
  const raw = await generateWithGemini(prompt, apiKey, model);

  // Clean potential markdown wrapping
  let cleaned = raw.trim();
  if (cleaned.startsWith("```")) {
    cleaned = cleaned.replace(/^```(?:json)?\n?/, "").replace(/\n?```$/, "");
  }
  // Handle trailing text after JSON
  const lastBrace = cleaned.lastIndexOf("}");
  if (lastBrace > 0 && lastBrace < cleaned.length - 1) {
    cleaned = cleaned.slice(0, lastBrace + 1);
  }

  let data: any = {};
  try {
    data = JSON.parse(cleaned);
  } catch {
    try {
      const match = cleaned.match(/^\{[\s\S]*\}/);
      if (match) data = JSON.parse(match[0]);
    } catch {}
  }

  // ── Step 3: Merge — CODE-extracted dates OVERRIDE AI dates ──
  let finalDates = Array.isArray(data.importantDates) ? data.importantDates : [];
  if (preExtractedDates.length > 0) {
    // Code-extracted dates are authoritative — merge them in
    for (const extracted of preExtractedDates) {
      const existingIdx = finalDates.findIndex((d: any) => d.label === extracted.label);
      if (existingIdx >= 0) {
        finalDates[existingIdx] = extracted; // Override AI date with code-extracted
      } else {
        finalDates.push(extracted);
      }
    }
  }

  // Merge eligibility — code-extracted overrides AI
  const eligibility = preExtractedEligibility
    ? preExtractedEligibility
    : data.contentModules?.eligibility ?? {};

  return {
    shortName: data.shortName ?? "",
    conductingBody: data.conductingBody ?? "",
    officialWebsite: data.officialWebsite ?? "",
    importantDates: finalDates,
    vacancy: data.vacancy ?? null,
    status: data.status ?? "upcoming",
    hasNotification: data.hasNotification ?? true,
    hasApplication: data.hasApplication ?? true,
    hasAdmitCard: data.hasAdmitCard ?? true,
    hasSyllabus: data.hasSyllabus ?? true,
    hasAnswerKey: data.hasAnswerKey ?? true,
    hasResult: data.hasResult ?? true,
    hasCutoff: data.hasCutoff ?? true,
    hasCounselling: data.hasCounselling ?? false,
    seoTitle: data.seoTitle ?? "",
    seoDescription: data.seoDescription ?? "",
    tags: Array.isArray(data.tags) ? data.tags : [],
    faqs: Array.isArray(data.faqs) ? data.faqs : [],
    contentModules: {
      ...(data.contentModules ?? {}),
      // Inject code-extracted eligibility into content modules
      ...(preExtractedEligibility ? { eligibility: preExtractedEligibility } : {}),
      // Inject code-extracted fees into content modules
      ...(preExtractedFees ? { "application-process": { ...(data.contentModules?.["application-process"] ?? {}), fee: `<p>General/Others: ₹${preExtractedFees.general.toLocaleString()}, SC/ST/PwBD: ₹${preExtractedFees.sc.toLocaleString()}. One-time fee, non-refundable.</p>` } } : {}),
    },
  };
}
